-- Function: public.fn_get_platform_all_branches
-- Backup generated on 2026-10-25 20:33:37

CREATE OR REPLACE FUNCTION public.fn_get_platform_all_branches()  RETURNS TABLE(id uuid, organization_id uuid, name character varying, location character varying, is_active boolean, created_at timestamp with time zone, organization_name character varying, effective_location text, classrooms_count integer, children_count integer)  LANGUAGE sql  STABLE AS $function$     SELECT          b.id AS id,         b.organization_id AS organization_id,         b.name AS name,         b.location AS location,         b.is_active AS is_active,         b.created_at AS created_at,         o.name AS organization_name,         COALESCE(b.location, o.location, 'Location unspecified') AS effective_location,         COALESCE((SELECT COUNT(*) FROM classrooms c WHERE c.branch_id = b.id), 0)::int AS classrooms_count,         COALESCE((SELECT COUNT(*) FROM children ch JOIN classrooms c ON ch.classroom_id = c.id WHERE c.branch_id = b.id), 0)::int AS children_count     FROM branches b     JOIN organizations o ON b.organization_id = o.id     ORDER BY o.name, b.name; $function$ ;
